function validate([points]) {
  if (!Array.isArray(points) || points.length < 1 || points.length > 50) return 'points needs 1 to 50 points.';
  const seen = new Set();
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2 || !p.every(Number.isInteger)) return 'Each point is a pair of integers [x, y].';
    if (p[0] < 0 || p[1] < 0 || p[0] > 40000 || p[1] > 40000) return 'Coordinates are between 0 and 40000.';
    const key = p[0] + ',' + p[1];
    if (seen.has(key)) return 'All points must be different.';
    seen.add(key);
  }
  return null;
}

