function minAreaFreeRect(points) {
  const groups = new Map();
  for (let i = 0; i < points.length; i++) {
    for (let j = i + 1; j < points.length; j++) {
      const [x1, y1] = points[i];
      const [x2, y2] = points[j];
      const length = (x1 - x2) ** 2 + (y1 - y2) ** 2;
      const key = `${x1 + x2},${y1 + y2},${length}`;
      if (!groups.has(key)) {
        groups.set(key, []);
      }
      groups.get(key).push([i, j]);
    }
  }

  let best = Infinity;
  for (const pairs of groups.values()) {
    for (let a = 0; a < pairs.length; a++) {
      for (let b = a + 1; b < pairs.length; b++) {
        const corner = points[pairs[a][0]];
        const next = points[pairs[b][0]];
        const other = points[pairs[b][1]];
        const side1 = Math.hypot(corner[0] - next[0], corner[1] - next[1]);
        const side2 = Math.hypot(corner[0] - other[0], corner[1] - other[1]);
        best = Math.min(best, side1 * side2);
      }
    }
  }
  return best === Infinity ? 0 : best;
}

