function minAreaFreeRect(points) {
  // Try every corner a with two neighbours b and c at a right angle, then look for the fourth corner.
  let best = 0;
  for (const a of points) {
    for (const b of points) {
      for (const c of points) {
        if (a === b || a === c || b === c) continue;
        const ux = b[0] - a[0], uy = b[1] - a[1], vx = c[0] - a[0], vy = c[1] - a[1];
        if (ux * vx + uy * vy !== 0) continue;
        const dx = b[0] + c[0] - a[0], dy = b[1] + c[1] - a[1];
        if (!points.some(p => p[0] === dx && p[1] === dy)) continue;
        const area = Math.sqrt(ux * ux + uy * uy) * Math.sqrt(vx * vx + vy * vy);
        if (best === 0 || area < best) best = area;
      }
    }
  }
  return best;
}

