function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const target = size === 'large' ? 50 : int(1, 9);
  const span = size === 'large' ? (rand() < 0.5 ? int(9, 14) : 40000) : int(3, 6);
  const ox = int(0, 40000 - span), oy = int(0, 40000 - span);
  const seen = new Set(), points = [];
  const add = (x, y) => {
    if (points.length >= target || x < ox || y < oy || x > ox + span || y > oy + span || seen.has(x + ',' + y)) return;
    seen.add(x + ',' + y);
    points.push([x, y]);
  };
  // Plant some rotated rectangles so the answer is often non-zero.
  const planted = size === 'large' ? int(3, 10) : int(0, 2);
  const reach = Math.max(1, Math.floor(span / 2));
  for (let t = 0; t < planted; t++) {
    const a = int(-reach, reach), b = int(-reach, reach);
    if (a === 0 && b === 0) continue;
    const g = gcd(Math.abs(a), Math.abs(b)), q = int(1, 3) * (rand() < 0.5 ? -1 : 1);
    const wx = (-b / g) * q, wy = (a / g) * q;
    const px = ox + int(0, span), py = oy + int(0, span);
    for (const [x, y] of [[px, py], [px + a, py + b], [px + wx, py + wy], [px + a + wx, py + b + wy]]) add(x, y);
  }
  while (points.length < target) add(ox + int(0, span), oy + int(0, span));
  // Shuffle so planted corners are not adjacent.
  for (let i = points.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [points[i], points[j]] = [points[j], points[i]];
  }
  return [points];
}
